[[vk::binding(0, 0)]] RWTexture2D<float4> gOutput;
[[vk::binding(1, 0)]] cbuffer Host {
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};
[[vk::binding(2, 0)]] RaytracingAccelerationStructure gScene;

struct Payload { float4 c; };

[shader("raygeneration")]
void RayGen()
{
    uint2 idx = DispatchRaysIndex().xy;
    uint2 dim = DispatchRaysDimensions().xy;
    float2 uv = (float2(idx) + 0.5) / float2(dim);
    float2 ndc = uv * 2.0 - 1.0;
    ndc.y = -ndc.y;
    float aspect = float(dim.x) / float(dim.y);
    float3 dir = normalize(float3(ndc.x * aspect, ndc.y, 2.0));

    RayDesc ray;
    ray.Origin = float3(0, 0.5, -3);
    ray.TMin = 0.001;
    ray.Direction = dir;
    ray.TMax = 100.0;

    Payload p;
    p.c = float4(0, 0, 0, 1);
    TraceRay(gScene, RAY_FLAG_NONE, 0xFF, 0, 0, 0, ray, p);
    gOutput[idx] = p.c;
}

struct Payload { float4 c; };
[shader("miss")]
void Miss(inout Payload p)
{
    float3 dir = WorldRayDirection();
    float sky = saturate(0.5 + dir.y * 0.5);
    p.c = float4(lerp(float3(0.8, 0.9, 1.0), float3(0.3, 0.5, 0.9), sky), 1.0);
}

[[vk::binding(1, 0)]] cbuffer Host {
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

struct Payload { float4 c; };

[shader("anyhit")]
void AnyHit(inout Payload p, in BuiltInTriangleIntersectionAttributes a)
{
    float2 bary = a.barycentrics;
    float alpha = 0.5 + 0.5 * sin(bary.x * 20.0 + time_sim_ms * 0.003);
    if (alpha < 0.5)
        IgnoreHit();
}

struct Payload { float4 c; };

[shader("closesthit")]
void ClosestHit(inout Payload p, in BuiltInTriangleIntersectionAttributes a)
{
    float3 bary = float3(1.0 - a.barycentrics.x - a.barycentrics.y, a.barycentrics.x, a.barycentrics.y);
    float3 col = float3(bary.x * 0.8 + 0.1, bary.y * 0.6 + 0.2, bary.z * 0.7 + 0.1);
    p.c = float4(col, 1.0);
}
